// Story of the day: a story told one illustrated chapter a day. Each day's
// chapter carries on from a running summary of the ones before it, and when a
// story reaches its last chapter, the next day starts a new one. Needs an
// OpenAI API key.
import { apiKey, askJson, paint, pictureFor, readRecord, sizeFor, dayKey } from './ai'

const SYSTEM = `You write a serialized story for a picture frame on someone's wall: one short chapter a day.
Write warm, vivid, well-paced prose for adults and children alike, with a small hook at the end of each chapter.
Keep the cast, places and facts consistent with the summary of the story so far. Never use real people.
Answer JSON only:
{"storyTitle": "the story's title (keep it once set)", "chapterTitle": "this chapter's title, at most 5 words",
"text": "the chapter, 110 to 140 words, in two or three short paragraphs separated by blank lines",
"summary": "the whole story so far, this chapter included, in at most 120 words",
"illustration": "a prompt for this chapter's illustration, 40 to 70 words: the scene, the characters' look, the light. No text."}`

const STYLES: Record<string, string> = {
  storybook: 'a classic storybook illustration in ink and watercolor',
  gouache: 'a rich gouache painting like a modern picture book',
  engraving: 'a Victorian engraving, finely cross-hatched',
  anime: 'a soft hand-painted animation background with characters',
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const now = new Date()
  return pictureFor(app, 'chapter', dayKey(now), 'ai-scenes/story-of-the-day', (path) => {
    const key = apiKey()
    const before = readRecord(app.state.chapter)
    const last = before && before.text && before.text.chapter ? before.text : null
    const total = Math.max(3, Math.min(30, Number(app.config.chapters) || 7))
    const fresh = !last || last.chapter >= (last.total || total)
    const chapter = fresh ? 1 : last.chapter + 1
    const genre = String(app.config.genre || 'a cozy mystery')
    const hero = String(app.config.hero || '').trim()
    const ask = fresh
      ? `Begin a new story: ${genre}${hero ? `, about ${hero}` : ''}. This is chapter 1 of ${total}. Invent a title.`
      : `Continue "${last.storyTitle}" (${genre}). The story so far: ${last.summary}\n\nWrite chapter ${chapter} of ${total}.` +
        (chapter === total ? ' It is the last chapter: bring the story to a satisfying end.' : '')
    const written = askJson(key, String(app.config.textModel || 'gpt-6.1-terra'), SYSTEM, ask)
    const style = STYLES[String(app.config.illustration)] || STYLES.storybook
    const width = context.targetWidth || context.imageWidth || app.frame.width
    const height = context.targetHeight || context.imageHeight || app.frame.height
    const model = String(app.config.imageModel || 'gpt-image-2')
    paint(key, model, `${written.illustration}\n\nDrawn as ${style}. No text or lettering.`, sizeFor(model, width, height, app.frame.embedded), path, app.frame.embedded)
    return {
      storyTitle: String(written.storyTitle || (last && !fresh ? last.storyTitle : 'A story')),
      chapterTitle: String(written.chapterTitle || ''),
      text: String(written.text || ''),
      summary: String(written.summary || ''),
      chapter,
      total,
    }
  })
}

