// The page beside the day's illustration: the story's title, the chapter's
// number and title, and the chapter itself, set like a book.
import { readRecord } from './record'

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const record = readRecord(app.state.chapter)
  const text = record && record.text
  const u = Math.min(W, H) / 100
  const pad = Math.round(u * 6)

  const round = roundColumn(app, W, H)
  if (round && !text) {
    // On a round panel, the note poured into the circle's right-hand part.
    const R = round.r
    const lines = flowIntoCircleCentred(
      [
        { text: 'Once upon a time…', className: `font-[Cormorant_Garamond] font-bold text-[${Math.round(R * 0.11)}px] leading-[${Math.round(R * 0.13)}px] text-[#2a2118]`, lead: Math.round(R * 0.13), gap: Math.round(R * 0.04) },
        { text: record && record.error ? String(record.error) : 'The first chapter is written in the morning. Add an OpenAI API key in the frame settings.', className: 'font-[Cormorant_Garamond] text-[15px] leading-[20px] text-[#6d5d4b]', lead: 20, gap: 0 },
      ],
      Math.round(R * 0.2),
      H - Math.round(R * 0.14),
      round,
      Math.round(R * 0.07),
    )
    return (
      <div className={`relative w-[${W}px] h-[${H}px] bg-[#f6f0e4]`}>
        {lines.map((line) => (
          <div className={`absolute top-[${line.y}px] left-[${line.left}px] w-[${line.width}px] whitespace-nowrap ${line.className}`}>{line.text}</div>
        ))}
      </div>
    )
  }

  if (!text) {
    return (
      <div className={`flex flex-col w-full h-full bg-[#f6f0e4] p-[${pad}px] justify-center`}>
        <div className={`font-[Cormorant_Garamond] font-bold text-[${Math.round(u * 7)}px] text-[#2a2118]`}>Once upon a time…</div>
        <div className={`font-[Cormorant_Garamond] text-[${Math.round(u * 4.5)}px] text-[#6d5d4b] mt-[${Math.round(u * 2)}px]`}>
          {record && record.error ? record.error : 'The first chapter is written in the morning. Add an OpenAI API key in the frame settings.'}
        </div>
      </div>
    )
  }

  if (round) {
    // On a round panel: the chapter poured into the circle's right half, its
    // lines running out to the rim.
    const R = round.r
    const size = Math.max(14, Math.round(R * 0.068))
    const lines = flowIntoCircle(
      [
        { text: `Chapter ${text.chapter} of ${text.total}`, className: 'font-[Cormorant_Garamond] uppercase text-[14px] leading-[18px] text-[#9b7b55]', lead: 18, gap: 2 },
        { text: String(text.chapterTitle), className: `font-[Cormorant_Garamond] font-bold text-[${Math.round(R * 0.095)}px] leading-[${Math.round(R * 0.11)}px] text-[#2a2118]`, lead: Math.round(R * 0.11), gap: Math.round(R * 0.06), lines: 2 },
        { text: String(text.text), className: `font-[Cormorant_Garamond] text-[${size}px] leading-[${Math.round(size * 1.3)}px] text-[#2a2118]`, lead: Math.round(size * 1.3), gap: 0 },
      ],
      Math.round(R * 0.2),
      H - Math.round(R * 0.12),
      round,
      Math.round(R * 0.07),
    )
    return (
      <div className={`relative w-[${W}px] h-[${H}px] bg-[#f6f0e4]`}>
        {lines.map((line) => (
          <div className={`absolute top-[${line.y}px] left-[${line.left}px] w-[${line.width}px] whitespace-nowrap ${line.className}`}>{line.text}</div>
        ))}
      </div>
    )
  }

  // As big as the chapter allows: shorter text, bigger type.
  const words = String(text.text).split(/\s+/).length
  const area = (W - pad * 2) * (H - pad * 2 - u * 22)
  const body = Math.round(Math.max(u * 3, Math.min(u * 5.2, Math.sqrt(area / (words * 4.6)))))
  const paragraphs = String(text.text).split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean)

  return (
    <div className={`flex flex-col w-full h-full bg-[#f6f0e4] px-[${pad}px] py-[${Math.round(pad * 0.8)}px]`}>
      <div className={`font-[Cormorant_Garamond] uppercase text-[${Math.round(u * 2.8)}px] text-[#9b7b55]`}>
        {`${text.storyTitle} · Chapter ${text.chapter} of ${text.total}`}
      </div>
      <div className={`font-[Cormorant_Garamond] font-bold text-[${Math.round(u * 6.4)}px] leading-tight text-[#2a2118] mt-[${Math.round(u)}px]`}>
        {text.chapterTitle}
      </div>
      <div className={`h-[2px] w-[${Math.round(u * 12)}px] bg-[#9b7b55] mt-[${Math.round(u * 2)}px] mb-[${Math.round(u * 2.2)}px]`} />
      <div className="flex flex-col flex-1 min-h-0 overflow-hidden">
        {paragraphs.map((p) => (
          <div className={`font-[Cormorant_Garamond] text-[${body}px] leading-snug text-[#2a2118] mb-[${Math.round(body * 0.6)}px]`}>{p}</div>
        ))}
      </div>
      {text.chapter === text.total ? (
        <div className={`font-[Cormorant_Garamond] font-bold text-[${Math.round(u * 3.4)}px] text-[#9b7b55] text-center`}>The End</div>
      ) : null}
    </div>
  )
}

// On a round panel only the circle inside the square shows, and the scene's
// split puts this page in its right-hand column: the panel's full height, up
// to its right edge. Where the circle is in the page's own pixels, or null on
// every other panel and in any other room.
function roundColumn(app: FrameOSApp, W: number, H: number) {
  const side = Math.min(app.frame.width, app.frame.height)
  if (app.frame.round !== true || Math.abs(H - side) > 1 || W >= side - 1) return null
  return { cx: W - side / 2, cy: H / 2, r: side / 2 }
}

type Flowed = { text: string; className: string; y: number; left: number; width: number }

// The same, moved down to the middle of the room when it leaves room below.
function flowIntoCircleCentred(
  blocks: { text: string; className: string; lead: number; gap: number; lines?: number }[],
  top: number,
  bottom: number,
  at: { cx: number; cy: number; r: number },
  seam: number,
) {
  const first = flowIntoCircle(blocks, top, bottom, at, seam)
  const last = first[first.length - 1]
  const slack = last ? bottom - (last.y + blocks[blocks.length - 1].lead) : 0
  if (slack < 20) return first
  const lower = flowIntoCircle(blocks, top + Math.round(slack / 2), bottom, at, seam)
  const said = (lines: Flowed[]) => lines.map((line) => line.text).join(' ')
  return said(lower) === said(first) ? lower : first
}

// Blocks of text poured into the circle from `top` to `bottom`: each line
// from the page's left edge (`seam` in) to the rim (12 px in), measured so
// nothing is cut. A block stops at its `lines`, the text at `bottom`, and
// what does not fit ends in "…".
function flowIntoCircle(
  blocks: { text: string; className: string; lead: number; gap: number; lines?: number }[],
  top: number,
  bottom: number,
  at: { cx: number; cy: number; r: number },
  seam: number,
) {
  const out: Flowed[] = []
  let y = top
  const shorten = (line: Flowed | undefined) => {
    if (line) line.text = line.text.includes(' ') ? line.text.replace(/\s+\S+$/, '…') : line.text + '…'
  }
  for (const block of blocks) {
    let used = 0
    const paragraphs = block.text.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean)
    for (let p = 0; p < paragraphs.length; p++) {
      const words = paragraphs[p].split(/\s+/)
      let k = 0
      while (k < words.length) {
        if (y + block.lead > bottom || (block.lines && used >= block.lines)) {
          shorten(used ? out[out.length - 1] : undefined)
          if (y + block.lead > bottom) return out
          p = paragraphs.length
          break
        }
        const dy = Math.max(Math.abs(y - at.cy), Math.abs(y + block.lead - at.cy))
        const half = Math.sqrt(Math.max(0, at.r * at.r - dy * dy))
        const left = Math.max(0, at.cx - half) + seam
        const width = Math.floor(at.cx + half - 12 - left)
        if (width < block.lead * 3) {
          y += block.lead
          continue
        }
        const tries = []
        for (let n = 1; n <= Math.min(words.length - k, 24); n++) tries.push(words.slice(k, k + n).join(' '))
        const heights = frameos.measureText(tries, { className: block.className, width })
        let n = 1
        while (n < tries.length && heights[n] <= heights[0]) n++
        out.push({ text: tries[n - 1], className: block.className, y, left: Math.round(left), width })
        k += n
        used++
        y += block.lead
      }
      if (p < paragraphs.length - 1) y += Math.round(block.lead * 0.35)
    }
    y += block.gap
  }
  return out
}

